import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.BKVF-9lJ.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md","lastUpdated":1791840224000}'),n={name:"getting-started.md"};function r(d,e,i,c,p,l){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>MFE Forge is a command-line tool plus a set of small runtime packages for building <strong>micro frontends (MFEs)</strong> with <strong>Vite</strong>, <strong>React 19</strong> and <strong>Module Federation</strong>. The CLI scaffolds a workspace, generates hosts and remote applications, keeps the host&#39;s federation configuration in sync with the remotes that exist on disk, and inspects the result. The runtime packages give those applications error boundaries, lazy remote loading, an event bus, routing helpers, shared Zustand stores, design tokens and test helpers.</p><div class="warning custom-block"><p class="custom-block-title">Pre-1.0 software</p><p>MFE Forge is on the <code>0.x</code> line (current release: <code>0.1.1</code>). Minor versions may contain breaking changes. npm versions <code>2.0.0</code> to <code>8.1.0</code> of <code>mfe-forge</code> are deprecated prototype releases; use <code>0.1.0</code> or later.</p></div><h2 id="why-mfe-forge" tabindex="-1">Why MFE Forge <a class="header-anchor" href="#why-mfe-forge" aria-label="Permalink to &quot;Why MFE Forge&quot;">​</a></h2><p>Module Federation lets independently built applications share code at runtime, but a working setup needs many pieces that are tedious to keep consistent by hand:</p><ul><li>each remote needs a unique federation name, a free dev port and an exposed entry;</li><li>each host needs a <code>remotes</code> entry and a TypeScript module declaration for every remote it consumes;</li><li>React, React DOM, React Router and Zustand must be declared as shared singletons on both sides;</li><li>the host must survive a remote that is down or throws.</li></ul><p>MFE Forge encodes these conventions. You name an application <code>scope/name</code>, and the CLI derives the directory, the package name, the federation name, the port and the dev script from it, then wires remotes into the host of the same scope.</p><h2 id="feature-overview" tabindex="-1">Feature overview <a class="header-anchor" href="#feature-overview" aria-label="Permalink to &quot;Feature overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>What you get</th><th>Reference</th></tr></thead><tbody><tr><td>Project scaffolding</td><td><code>init</code> creates a workspace with <code>apps/</code>, <code>packages/</code>, <code>tools/</code>, a root <code>package.json</code>, <code>tsconfig.base.json</code> and <code>mfeforge.config.js</code></td><td><a href="./cli/init"><code>init</code></a></td></tr><tr><td>Code generation</td><td><code>generate</code> (alias <code>g</code>) creates hosts, remote apps, packages, libraries and a design-system package from templates</td><td><a href="./cli/generate"><code>generate</code></a></td></tr><tr><td>Federation sync</td><td><code>sync</code> rewrites each host&#39;s <code>remotes</code> block and <code>src/remotes/declarations.d.ts</code>, and writes <code>mfe-forge.manifest.json</code></td><td><a href="./cli/sync"><code>sync</code></a></td></tr><tr><td>Orchestration</td><td><code>dev</code>, <code>build</code> and <code>test</code> run the per-app scripts for all apps, one scope or one app</td><td><a href="./cli/dev"><code>dev</code></a>, <a href="./cli/build"><code>build</code></a></td></tr><tr><td>Diagnostics</td><td><code>doctor</code>, <code>status</code>, <code>graph</code>, <code>inspect</code>, <code>deps</code>, <code>check</code>, <code>migrate</code>; most support <code>--json</code></td><td><a href="./cli/doctor"><code>doctor</code></a>, <a href="./cli/diagnostics">diagnostics</a></td></tr><tr><td>Configuration</td><td><code>mfeforge.config.*</code>, validated with a zod schema; <code>config</code> reads and edits it</td><td><a href="./config">Configuration</a></td></tr><tr><td>Runtime</td><td><code>@mfe-forge/core</code>, <code>router</code>, <code>store</code>, <code>design</code>, <code>testing</code></td><td><a href="./packages/">Packages</a></td></tr></tbody></table><h2 id="how-the-pieces-fit" tabindex="-1">How the pieces fit <a class="header-anchor" href="#how-the-pieces-fit" aria-label="Permalink to &quot;How the pieces fit&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>            you                                   mfe-forge CLI</span></span>
<span class="line"><span>             |                                         |</span></span>
<span class="line"><span>             |  mfe-forge generate app shop/catalog    |</span></span>
<span class="line"><span>             +----------------------------------------&gt;|</span></span>
<span class="line"><span>                                                       | 1. copies templates/app into apps/shop/catalog</span></span>
<span class="line"><span>                                                       | 2. picks a free port in dev.portRange</span></span>
<span class="line"><span>                                                       | 3. adds &quot;dev:shop:catalog&quot; to the root package.json</span></span>
<span class="line"><span>                                                       | 4. if apps/shop/host exists, rewrites its remotes</span></span>
<span class="line"><span>                                                       |    block and declarations.d.ts</span></span>
<span class="line"><span>                                                       v</span></span>
<span class="line"><span>  apps/shop/host  (federation name shopHostApp)       apps/shop/catalog  (shopCatalogApp)</span></span>
<span class="line"><span>  vite.config.ts                                      vite.config.ts</span></span>
<span class="line"><span>    remotes: {                                          exposes: { &#39;./App&#39;: &#39;./src/bootstrap.tsx&#39; }</span></span>
<span class="line"><span>      shopCatalogApp:                                   filename: &#39;remoteEntry.js&#39;</span></span>
<span class="line"><span>       &#39;http://localhost:3001/assets/remoteEntry.js&#39;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  src/App.tsx                                          uses @mfe-forge/core, router, store</span></span>
<span class="line"><span>    React.lazy(() =&gt; import(&#39;shopCatalogApp/App&#39;))</span></span></code></pre></div><p>At runtime the host loads <code>remoteEntry.js</code> from the remote&#39;s URL, negotiates the shared singletons and renders the exposed component. <code>@mfe-forge/core</code> wraps that render in an error boundary with a retry button and an accessible loading state. See <a href="./concepts">Concepts</a> for each term and <a href="./architecture">Architecture</a> for the internals.</p><h2 id="status-and-maturity" tabindex="-1">Status and maturity <a class="header-anchor" href="#status-and-maturity" aria-label="Permalink to &quot;Status and maturity&quot;">​</a></h2><p>This summary is drawn from the project <a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/blob/main/ROADMAP.md" target="_blank" rel="noreferrer">roadmap</a> and the <a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/blob/main/docs/ai/known-issues.md" target="_blank" rel="noreferrer">known issues</a> list.</p><p>What works today:</p><ul><li>Scaffolding with <code>init</code> and <code>generate</code>, deterministic naming and port allocation.</li><li>Idempotent <code>sync</code> with <code>--dry-run</code>, <code>--check</code> and <code>--json</code> modes.</li><li><code>build</code> and <code>test</code> exit non-zero when a target fails (<code>2</code> for task failures, <code>3</code> for configuration errors).</li><li>Runtime error boundary with <code>role=&quot;alert&quot;</code> and a &quot;Try again&quot; button that re-imports the remote, and a loading fallback with <code>role=&quot;status&quot;</code>.</li></ul><p>Known limitations you should plan around:</p><ul><li>Templates use <a href="https://github.com/originjs/vite-plugin-federation" target="_blank" rel="noreferrer"><code>@originjs/vite-plugin-federation</code></a> and pin Vite <code>~5.4</code>. Moving to Module Federation 2.0 (<code>@module-federation/vite</code>) is the main item of roadmap phase B (<code>0.2.0</code>).</li><li>The host&#39;s <code>remotes</code> block is rewritten <strong>as text</strong>. Remotes declared through variables or spread expressions are not understood.</li><li><code>mfeforge.config.ts</code> is evaluated without a TypeScript compiler. Imports are stripped, so the default export must be a self-contained object literal.</li><li>Remote URLs are always <code>http://localhost:&lt;port&gt;/assets/remoteEntry.js</code>. There is no per-environment remote URL support yet; see <a href="./publishing">Publishing</a>.</li><li>The generated root <code>package.json</code> lists <code>apps/*</code> as a workspace, but apps live two levels deep (<code>apps/&lt;scope&gt;/&lt;name&gt;</code>). Add <code>apps/*/*</code> yourself; see <a href="./installation#workspace-layout-fix">Installation</a>.</li><li>There is no end-to-end test of <code>init → generate → install → build → load remote</code> yet.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./installation">Installation</a>: requirements and package manager support.</li><li><a href="./quick-start">Quick start</a>: a host and a remote running in a few minutes.</li><li><a href="./tutorials/example-project">Example project</a>: a complete walkthrough with two remotes and shared state.</li><li><a href="./cli/">CLI reference</a>: every command and flag.</li></ul>`,20)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
